import type { ComponentType } from "react";

/**
 * Brand marks for the Stack section, generated once from two sources and
 * committed as static data — no simple-icons/iconify dependency at runtime.
 *
 * - SIMPLE: official path + hex from the simple-icons catalogue. Rendered as
 *   a single-colour <path>, tinted with the brand hex.
 * - RAW: pre-coloured multi-path logos for brands simple-icons does not
 *   carry (AWS, Tableau, Power BI, dbt, Dagster, ...), sourced from the
 *   Iconify "logos"/"devicon" collections or, for Dagster, the vendor's own
 *   site. Injected via dangerouslySetInnerHTML because hand-converting each
 *   attribute (fill-rule, clip-rule, ...) to JSX for ~10 multi-path logos
 *   isn't worth it for static, build-time-authored markup.
 *
 * A handful of requested items (SQL, Transformers, BERT, NLP, FAISS, CI/CD)
 * have no public brand mark anywhere — they simply have no entry here, and
 * TechChip renders those as a plain text pill instead of guessing an icon.
 */

type SimpleEntry = { hex: string; path: string };
type RawEntry = { viewBox: string; html: string; tint?: string };

