/**
 * Some brand hexes are themselves achromatic (Express ships "#0A0A0A" — our
 * own near-black), which would make the mark invisible in dark mode and a
 * dead flat blob in light mode. Anything with negligible saturation falls
 * back to currentColor so it tracks the theme instead of vanishing in one of them.
 */
function isNeutralHex(hex: string): boolean {
  const r = parseInt(hex.slice(0, 2), 16);
  const g = parseInt(hex.slice(2, 4), 16);
  const b = parseInt(hex.slice(4, 6), 16);
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const range = 255 - Math.abs(max + min - 255);
  const saturation = range === 0 ? 0 : (max - min) / range;
  return saturation < 0.08;
}

function SimpleMark({ hex, path, size = 16 }: SimpleEntry & { size?: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" aria-hidden focusable="false">
      <path d={path} fill={isNeutralHex(hex) ? "currentColor" : `#${hex}`} />
    </svg>
  );
}

function RawMark({ viewBox, html, tint, size = 16 }: RawEntry & { size?: number }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox={viewBox}
      aria-hidden
      focusable="false"
      style={tint ? { color: tint } : undefined}
      dangerouslySetInnerHTML={{ __html: html }}
    />
  );
}

export const TECH_ICONS: Record<string, ComponentType<{ size?: number }>> = {};

for (const [label, entry] of Object.entries(SIMPLE)) {
  TECH_ICONS[label] = ({ size }) => <SimpleMark {...entry} size={size} />;
}

for (const [label, entry] of Object.entries(RAW)) {
  TECH_ICONS[label] = ({ size }) => <RawMark {...entry} size={size} />;
}
